sql.if:

AND (
        UPPER(A.AUTH_CODE) LIKE #{keywordLike}
     OR UPPER(A.AUTH_NAME) LIKE #{keywordLike}
    )

mapper.insert:
/* setAuthGroup */
INSERT INTO TM_AUTHXM (
            AUTH_CODE
          , AUTH_NAME
          , USEE_YSNO
          , REGI_ADMN
          , REGI_DATE
          , UPDT_ADMN
          , UPDT_DATE
) VALUES (  #{authCode}
          , #{authName}
          , #{useeYsno}
          , #{regiAdmn}
          , CURRENT_TIMESTAMP
          , #{updtAdmn}
          , CURRENT_TIMESTAMP
)

mapper.update:
UPDATE /* uptAuthGroup */
       TM_AUTHXM
   SET AUTH_NAME = #{authName}
     , USEE_YSNO = #{useeYsno}
     , UPDT_ADMN = #{updtAdmn}
     , UPDT_DATE = CURRENT_TIMESTAMP
 WHERE AUTH_CODE = #{authCode}

mapper.insert:
/* setAuthMenu */
INSERT INTO TB_AUTHMN (
            AUTH_CODE
          , MENU_NUMB
          , SUBX_NUMB
          , READ_YSNO
          , WRIT_YSNO
          , DELT_YSNO
          , REGI_ADMN
          , REGI_DATE
          , UPDT_ADMN
          , UPDT_DATE
) VALUES (  #{authCode}
          , #{menuNumb}
          , #{subxNumb}
          , #{readYsno}
          , #{writYsno}
          , #{deltYsno}
          , #{regiAdmn}
          , CURRENT_TIMESTAMP
          , #{updtAdmn}
          , CURRENT_TIMESTAMP
)

mapper.delete:
DELETE /* delAuthMenu */
  FROM TB_AUTHMN
 WHERE AUTH_CODE = #{authCode}

DELETE /* delAuthGroup */
  FROM TM_AUTHXM
 WHERE AUTH_CODE = #{authCode}
